class Ball extends Circle {

   //Attribute
   String farbe;
   int radius;
   int startX = 300;
   int startY = 200;
   float geschwindigkeit; 
   float richtung; 

   //Referenzattribute
   Spiel meinSpiel;
   Schlaeger meinSchlaeger;

   //Konstruktor
   Ball(String _farbe, int _radius, Spiel _spiel, Schlaeger _schlaeger) 
   {
      super(startX, startY, _radius);
      farbe = _farbe;
      radius = _radius; 
      setFillColor(farbe);
      meinSpiel = _spiel;
      meinSchlaeger = _schlaeger;
   }


   //Methoden
   void act() {

      defineDirection(richtung);
      forward(geschwindigkeit);

      if(getCenterY() > 745) {
         meinSpiel.verliereLeben();
      }

      if(getCenterY() < 5) abprallenY();
      if(getCenterX() < 5) abprallenX(); 
      if(getCenterX() > 595) abprallenX(); 
      if(collidesWith(meinSchlaeger)) abprallenY();

   }

   void geheAufStart() 
   {
      moveTo(startX, startY);
      geschwindigkeit = 30;
      richtung = 315; 
   }

   void abprallenX() {
      richtung = 540 - richtung;
   } 

   void abprallenY() {
      richtung = 360 - richtung;
   } 

}

class Spiel extends Actor {

   //Attribute
   int punkte;
   int leben;

   Schlaeger meinSchlaeger;
   Ball meinBall;
   Text punkteText; 
   Text lebenText; 


   //Konstruktor
   Spiel() {
      punkte = 0;
      leben = 3; 
      meinSchlaeger = new Schlaeger("red", 80, this);
      meinBall = new Ball("green", 10, this, meinSchlaeger);
      punkteText = new Text(460, 5, 32, "Punkte: 0");
      punkteText.moveTo(this.getWorld().getWidth() - punkteText.getWidth() - 10, 5);
      lebenText = new Text(10, 5, 32, "Leben: 3"); 

      for (int i = 0; i < 40; i++)
      {
         new Block("blue",(i % 10) * 60, 50 + (i / 10) * 30, meinBall, this); 
      } 

      meinBall.geheAufStart();

   }

   //Methoden
   void act()
   {
      lebenText.setText("Leben: " + leben);
      punkteText.setText("Punkte: " + punkte); 

      if(leben == 0) {
         Text text = new Text(60, 200, 80, "GAME OVER"); 
         text.moveTo((this.getWorld().getWidth() / 2) - text.getWidth() / 2, 200);
         SystemTools.pause(200);
         System.exit(2);
      } if(punkte >= 40) {
         Text text = new Text(60, 200, 80, "GAME WON"); 
         text.moveTo((this.getWorld().getWidth() / 2) - text.getWidth() / 2, 200);
         SystemTools.pause(200);
         System.exit(1);
      }      
   }

   void verliereLeben()
   {
      leben--;
      meinBall.geheAufStart();
   }

   void punkteErhöhen() {
      punkte++;
      punkteText.moveTo(this.getWorld().getWidth() - punkteText.getWidth() - 10, 5);
   }
}

class Block extends Rectangle {

   //Attribute
   String farbe;

   //Referenzattribute
   Ball meinball;
   Spiel meinSpiel; 

   //Konstruktor
   Block(String _farbe, int x, int y, Ball _meinball, Spiel _meinSpiel)
  	{	
      super(x, y, 60, 30);
      farbe = _farbe;
      setFillColor(farbe);
      setBorderWidth(4); 
      setBorderColor("gray");
      meinball = _meinball;
      meinSpiel = _meinSpiel; 
   }

   //Methoden
   void act()
   {
      if(collidesWith(meinball))
      {
         meinball.abprallenY();
         meinSpiel.punkteErhöhen(); 
         destroy(); 
      }
   } 
}

class Schlaeger extends Rectangle {

   //Attribute
   String farbe;
   int groesse;
   int geschwindigkeit = 10; 
   Spiel meinSpiel;


   //Konstruktor
   Schlaeger(String _farbe, int _groesse, Spiel _meinSpiel) {
      super(300, 480, _groesse, 20);
      farbe = _farbe;
      groesse = _groesse;
      setFillColor(_farbe);
      meinSpiel = _meinSpiel;
   }

   //Methoden
   void act() { 
      if(isKeyDown("a")) {
         bewegeNachLinks(); 
      } 
      if(isKeyDown("d")) {
         bewegeNachRechts();
      }
   }

   void bewegeNachRechts()
   {
      move(geschwindigkeit, 0);
   }

   void bewegeNachLinks()
   {
      move(-geschwindigkeit, 0);
   }

   //Getter und Settermethoden
   String gibFarbe() return farbe;

   void setzeFarbe(String _farbe)
   {
      farbe = _farbe;
      setFillColor(farbe);
   }

   void setzeGröße(int _groesse) 
   {
      if(groesse > 40)
      {
         groesse = _groesse;
         setWidth(groesse);
      }
   }


}
